import React, { useState } from "react";
import Login from "./components/login";
import Dashboard from "./components/Dashboard";

/* OPTIONAL (if you have these pages) */
import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Preview from "./components/Preview";

function App() {

  const [user, setUser] = useState(null); // ✅ ALWAYS start null
  const [step, setStep] = useState("login");

  // ✅ HANDLE LOGIN
  const handleLogin = (userData) => {
    setUser(userData);

    // 🔥 CHECK IF USER ALREADY FILLED DATA
    const existingData = localStorage.getItem("userData");

    if (existingData) {
      setStep("dashboard"); // old user → dashboard
    } else {
      setStep("income"); // new user → start flow
    }
  };

  // ✅ HANDLE COMPLETE FLOW SAVE
  const handleFlowComplete = () => {
    localStorage.setItem("userData", "true"); // mark completed
    setStep("dashboard");
  };

  // ✅ LOGOUT
  const handleLogout = () => {
    localStorage.removeItem("user");
    setUser(null);
    setStep("login");
  };

  // =========================
  // 🔁 FLOW CONTROL
  // =========================

  if (step === "login") {
    return <Login onLogin={handleLogin} />;
  }

  if (step === "income") {
    return <IncomeCategory onNext={() => setStep("questionnaire")} />;
  }

  if (step === "questionnaire") {
    return <Questionnaire onNext={() => setStep("priority")} />;
  }

  if (step === "priority") {
    return <SpendingPriority onNext={() => setStep("budget")} />;
  }

  if (step === "budget") {
    return <BudgetLimits onNext={() => setStep("preview")} />;
  }

  if (step === "preview") {
    return <Preview onComplete={handleFlowComplete} />;
  }

  if (step === "dashboard") {
    return <Dashboard user={user} onLogout={handleLogout} />;
  }

  return null;
}

export default App;
